<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,AccountLifecycleState as S,AccountLifecycleProposal as P,RestrictionRecoveryRun as Run};
use App\Support\{RestrictionRecovery as R,AccountLifecycle as L,ReviewedImports};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\{DB,Crypt,Hash,Mail,Http};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Illuminate\Http\UploadedFile;
use Tests\Support\AuditFault;
use Tests\TestCase;
class RestrictionRecoveryTest extends TestCase
{
 use LazilyRefreshDatabase;
 private function state(User $u,string $status='Restricted'):S{$s=new S(['user_id'=>$u->id,'version'=>1,'status'=>$status,'review_on'=>today()->addDays(30)->toDateString()]);$s->proof=['fields'=>L::stateFields($s),'history'=>[]];$s->save();return$s;}
 private function f(int $count=1):array{
  $this->travelTo(now()->setDate(2026,11,15)->setTime(10,0));$admin=User::factory()->create(['role'=>'admin']);$ceo=User::factory()->create(['role'=>'ceo']);$targets=User::factory()->count($count)->create(['role'=>'tutor','active'=>false]);foreach($targets as$t){$this->state($t);}$sealed=L::ledger($admin);foreach($targets as$t){S::whereKey($t->id)->delete();$t->forceFill(['active'=>true])->save();}return compact('admin','ceo','targets','sealed');
 }
 private function make(array $f,?string $token=null):Run{$v=R::preview($f['admin'],$f['sealed']);return R::prepare($f['admin'],1,$f['sealed'],$v['hash'],$f['targets']->pluck('id')->all(),$token??(string)Str::uuid(),today()->addDays(14)->toDateString(),'Reviewed retention ref','Reviewed continuity ref','Checked post-restore restriction');}
 private function approved(array $f):Run{$r=$this->make($f);R::review($f['ceo'],1,$r,1,true,'Independent restore review');return$r->refresh();}
 private function reject(callable $fn):void{try{$fn();$this->fail('Expected checked refusal');}catch(ValidationException $e){$this->assertNotEmpty($e->errors());}}
 public function test_preview_authenticates_identity_and_does_not_change_access():void{$f=$this->f();$v=R::preview($f['admin'],$f['sealed']);$this->assertSame(1,$v['eligible']);$this->assertFalse($v['writes_performed']);$this->assertTrue($f['targets'][0]->fresh()->active);$this->assertDatabaseCount('account_lifecycle_proposals',0);}
 public function test_preparation_creates_drafts_without_disabling_anyone():void{$f=$this->f(2);$r=$this->make($f);$this->assertSame('Draft',$r->state);$this->assertDatabaseCount('account_lifecycle_proposals',2);foreach($f['targets']as$t){$this->assertTrue($t->fresh()->active);}}
 public function test_independent_review_and_atomic_application_reapply_restrictions():void{$f=$this->f(2);$a=Apprentice::factory()->create(['tutor_id'=>$f['targets'][0]->id]);$before=$a->fresh()->getAttributes();$r=$this->approved($f);R::apply($f['admin'],1,$r,2);foreach($f['targets']as$t){$this->assertFalse($t->fresh()->active);$this->assertTrue(L::blocked($t->fresh()));$this->assertSame(2,$t->fresh()->auth_version);}$this->assertSame($before,$a->fresh()->getAttributes());$this->assertSame('Applied',$r->fresh()->state);}
 public function test_sealed_archived_state_selects_archive_without_reactivation():void{$f=$this->f();$v=json_decode(Crypt::decryptString($f['sealed']),true);$v['rows'][0]['status']='Archived';$f['sealed']=Crypt::encryptString(json_encode($v));$r=$this->approved($f);R::apply($f['admin'],1,$r,2);$this->assertSame('Archived',S::find($f['targets'][0]->id)->status);}
 public function test_self_review_is_refused_without_explicit_ceo_override():void{$f=$this->f();$r=$this->make($f);$this->actingAs($f['admin'])->post('/restriction-recovery/'.$r->id.'/review',['version'=>1,'accept'=>1,'reference'=>'Self review refused','confirmed'=>1])->assertForbidden();$this->assertSame('Draft',$r->fresh()->state);}
 public function test_explicit_ceo_override_supports_recovery_with_one_current_operator():void{$f=$this->f();$f['admin']=$f['ceo'];$r=$this->make($f);R::review($f['ceo'],1,$r,1,true,'Explicit CEO recovery override',true);R::apply($f['ceo'],1,$r->refresh(),2);$this->assertTrue($r->fresh()->approval['ceo_override']);$this->assertFalse($f['targets'][0]->fresh()->active);}
 public function test_mismatched_identity_is_not_selectable_by_name():void{$f=$this->f();$f['targets'][0]->forceFill(['email'=>'different@example.test'])->save();$v=R::preview($f['admin'],$f['sealed']);$this->assertSame('identity',$v['rows'][0]['position']);$this->assertSame(0,$v['eligible']);$this->reject(fn()=>$this->make($f));}
 public function test_already_held_account_is_not_reapplied():void{$f=$this->f();$f['targets'][0]->forceFill(['active'=>false])->save();$this->assertSame('held',R::preview($f['admin'],$f['sealed'])['rows'][0]['position']);$this->reject(fn()=>$this->make($f));}
 public function test_later_restoration_decision_is_held_for_manual_review():void{$f=$this->f();$s=$this->state($f['targets'][0],'Active');$s->forceFill(['updated_at'=>now()->addMinute()])->save();$this->assertSame('later-decision',R::preview($f['admin'],$f['sealed'])['rows'][0]['position']);$this->reject(fn()=>$this->make($f));}
 public function test_damaged_managed_proof_is_not_repaired_implicitly():void{$f=$this->f();$s=$this->state($f['targets'][0]);$s->proof=['fields'=>[]];$s->save();$this->assertSame('proof',R::preview($f['admin'],$f['sealed'])['rows'][0]['position']);}
 public function test_actor_and_chief_executive_identities_are_protected():void{$f=$this->f();$v=json_decode(Crypt::decryptString($f['sealed']),true);foreach([$f['admin'],$f['ceo']]as$t){$v['rows'][]=['user_id'=>$t->id,'identity_hash'=>ReviewedImports::hash([$t->email,$t->created_at->toIso8601String()]),'status'=>'Restricted','version'=>1];}$sealed=Crypt::encryptString(json_encode($v));$rows=collect(R::preview($f['admin'],$sealed)['rows']);$this->assertSame('protected',$rows->firstWhere('user_id',$f['admin']->id)['position']);$this->assertSame('protected',$rows->firstWhere('user_id',$f['ceo']->id)['position']);}
 public function test_source_or_assignment_change_holds_stale_preview():void{$f=$this->f();$v=R::preview($f['admin'],$f['sealed']);Apprentice::factory()->create(['tutor_id'=>$f['targets'][0]->id]);$this->reject(fn()=>R::prepare($f['admin'],1,$f['sealed'],$v['hash'],$f['targets']->pluck('id')->all(),(string)Str::uuid(),today()->addDay()->toDateString(),'Retention ref','Handover ref','Restore decision ref'));}
 public function test_source_change_after_approval_rolls_back_all_targets():void{$f=$this->f(2);$r=$this->approved($f);$f['targets'][1]->increment('record_version');$this->reject(fn()=>R::apply($f['admin'],1,$r,2));foreach($f['targets']as$t){$this->assertTrue($t->fresh()->active);}$this->assertSame('Approved',$r->fresh()->state);}
 public function test_reviewer_revocation_prevents_application():void{$f=$this->f();$r=$this->approved($f);$f['ceo']->forceFill(['active'=>false])->save();$this->reject(fn()=>R::apply($f['admin'],1,$r,2));$this->assertTrue($f['targets'][0]->fresh()->active);}
 public function test_final_audit_failure_restores_passwords_sessions_proposals_and_accounts():void{$f=$this->f(2);$r=$this->approved($f);$before=$f['targets']->mapWithKeys(fn($u)=>[$u->id=>$u->fresh()->password]);DB::table('sessions')->insert(['id'=>'recovery-fixture','user_id'=>$f['targets'][0]->id,'payload'=>'fictional','last_activity'=>time()]);AuditFault::install('recovery_fail','portal_operations_events','fictional final audit failure','recovery_applied');try{R::apply($f['admin'],1,$r,2);$this->fail('Expected database failure');}catch(\Illuminate\Database\QueryException){}foreach($f['targets']as$t){$this->assertTrue($t->fresh()->active);$this->assertSame($before[$t->id],$t->fresh()->password);}$this->assertDatabaseCount('sessions',1);$this->assertSame(2,P::where('state','Approved')->count());$this->assertSame('Approved',$r->fresh()->state);}
 public function test_prepared_request_replay_is_idempotent_and_payload_bound():void{$f=$this->f();$token=(string)Str::uuid();$a=$this->make($f,$token);$b=$this->make($f,$token);$this->assertSame($a->id,$b->id);$this->assertDatabaseCount('restriction_recovery_runs',1);$this->assertDatabaseCount('account_lifecycle_proposals',1);}
 public function test_application_replay_does_not_revoke_credentials_twice():void{$f=$this->f();$r=$this->approved($f);R::apply($f['admin'],1,$r,2);$version=$f['targets'][0]->fresh()->auth_version;R::apply($f['admin'],1,$r,2);$this->assertSame($version,$f['targets'][0]->fresh()->auth_version);}
 public function test_duplicate_rows_in_authenticated_file_are_refused():void{$f=$this->f();$v=json_decode(Crypt::decryptString($f['sealed']),true);$v['rows'][]=$v['rows'][0];$this->reject(fn()=>R::preview($f['admin'],Crypt::encryptString(json_encode($v))));}
 public function test_wrong_key_or_tampered_file_is_refused_without_writes():void{$f=$this->f();$this->reject(fn()=>R::preview($f['admin'],$f['sealed'].'X'));$this->assertDatabaseCount('restriction_recovery_runs',0);}
 public function test_uploaded_file_and_review_forms_are_private_and_do_not_send():void{$f=$this->f();Mail::fake();Http::fake();$this->actingAs($f['admin'])->post('/restriction-recovery/preview',['ledger'=>UploadedFile::fake()->createWithContent('restrictions.gta',$f['sealed'])])->assertOk()->assertSee('Missing restriction')->assertHeader('Referrer-Policy','no-referrer');$r=$this->make($f);$this->get('/restriction-recovery/'.$r->id)->assertOk()->assertSee('Exact account proposals');Mail::assertNothingSent();Http::assertNothingSent();}
 #[\PHPUnit\Framework\Attributes\TestWith(['tutor'])]
 #[\PHPUnit\Framework\Attributes\TestWith(['apprentice'])]
 #[\PHPUnit\Framework\Attributes\TestWith(['employer'])]
 public function test_other_roles_cannot_read_or_prepare_recovery(string $role):void{$f=$this->f();$u=User::factory()->create(['role'=>$role]);$this->actingAs($u)->get('/restriction-recovery')->assertForbidden();$this->post('/restriction-recovery/preview',['ledger'=>UploadedFile::fake()->createWithContent('r.gta',$f['sealed'])])->assertForbidden();}
 public function test_batch_limit_refuses_more_than_twenty_five_before_proposals_are_created():void{$f=$this->f(26);$this->reject(fn()=>$this->make($f));$this->assertDatabaseCount('account_lifecycle_proposals',0);$this->assertDatabaseCount('restriction_recovery_runs',0);}
 public function test_rejected_batch_does_not_change_access_and_all_linked_proposals_are_rejected():void{$f=$this->f(2);$r=$this->make($f);R::review($f['ceo'],1,$r,1,false,'Returned after independent check');$this->assertSame('Rejected',$r->fresh()->state);$this->assertSame(2,P::where('state','Rejected')->count());foreach($f['targets']as$t){$this->assertTrue($t->fresh()->active);}}
 public function test_current_recovery_cli_reports_no_target_acceptance_or_side_effects():void{$this->artisan('gta:release-check46')->expectsOutputToContain('"actual_target_acceptance":false')->assertExitCode(0);$this->assertDatabaseCount('restriction_recovery_runs',0);}

}
